import os, socket, sys
_LOG = os.environ.get("NONET_LOG", "/dev/null")
_real_connect = socket.socket.connect
_real_connect_ex = socket.socket.connect_ex
def _blocked(self, address):
    if self.family in (socket.AF_INET, socket.AF_INET6):
        host = address[0]
        if host not in ("127.0.0.1", "::1", "localhost"):
            with open(_LOG, "a") as f:
                f.write(f"pid {os.getpid()} tried to connect to {address}\n")
            raise OSError(101, "Network is unreachable (simulated)")
    return None
def connect(self, address):
    _blocked(self, address); return _real_connect(self, address)
def connect_ex(self, address):
    try: _blocked(self, address)
    except OSError: return 101
    return _real_connect_ex(self, address)
socket.socket.connect = connect
socket.socket.connect_ex = connect_ex
_real_gai = socket.getaddrinfo
def getaddrinfo(host, *a, **k):
    if host not in (None, "127.0.0.1", "::1", "localhost"):
        with open(_LOG, "a") as f:
            f.write(f"pid {os.getpid()} tried to resolve {host}\n")
        raise socket.gaierror(-3, "Temporary failure in name resolution (simulated)")
    return _real_gai(host, *a, **k)
socket.getaddrinfo = getaddrinfo
